users = list_users({})
user_ids = for u in users { return u.id }
dates = ["2026-06-15", "2026-06-16", "2026-06-17", "2026-06-18", "2026-06-19"]

# Fetch availability for all users on all dates concurrently
avail = for u in user_ids {
  by_date = for d in dates {
    a = boundary retry 2 {
      return get_availability({ user_id: u, date: d })
    } catch err {
      return fail("AVAIL", err.code + ": " + err.message)
    }
    return { date: d, busy: a.busy if a.busy != null else [] }
  }
  return { user_id: u, days: by_date }
}

# Working hours: 09:00-17:00 UTC. 60-min meeting, start on 30-min boundary.
# Possible starts: 09:00, 09:30, 10:00, ..., 16:00
starts_hhmm = ["09:00","09:30","10:00","10:30","11:00","11:30","12:00","12:30","13:00","13:30","14:00","14:30","15:00","15:30","16:00"]

# Convert HH:MM to minutes since midnight
to_min = fun(t) {
  # inline via manual parse - no fun in runlet. Do parse inline.
  return 0
}

# Parse "HH:MM" to minutes
parse_min = for t in starts_hhmm {
  parts = text.split(t, ":")
  h = number.parse(parts[0])
  m = number.parse(parts[1])
  return { t: t, min: h * 60 + m }
}

# For each date in order, for each start in order, check if all users free
# Build busy intervals per user per date as list of {start_min, end_min}

result = fold acc = null for d in dates {
  skip if acc != null
  # For this date, get each user's busy in minutes
  day_check = fold found = null for slot in parse_min {
    skip if found != null
    s_min = slot.min
    e_min = s_min + 60
    # check all users free
    conflicts = fold c = 0 for u in avail {
      day = fold dd = null for x in u.days {
        skip if x.date != d
        return x
      }
      busy_list = day.busy if day != null else []
      hit = fold h = false for b in busy_list {
        skip if h
        bp = text.split(b.start, ":")
        bps = number.parse(bp[0]) * 60 + number.parse(bp[1])
        ep = text.split(b.end, ":")
        bpe = number.parse(ep[0]) * 60 + number.parse(ep[1])
        # overlap if s_min < bpe and e_min > bps
        overlaps = s_min < bpe and e_min > bps
        return overlaps
      }
      return c + (1 if hit else 0)
    }
    return { start: slot.t, date: d } if conflicts == 0 else null
  }
  return day_check
}

assert(result != null, "no slot found")

start_iso = result.date + "T" + result.start + ":00Z"
# end is start + 60 min
sp = text.split(result.start, ":")
sh = number.parse(sp[0])
sm = number.parse(sp[1])
total = sh * 60 + sm + 60
eh = number.floor(total / 60)
em = total - eh * 60
em_s = "00" if em == 0 else (text.slice("0" + json.encode(em), -2))
eh_s = text.slice("0" + json.encode(eh), -2)
end_iso = result.date + "T" + eh_s + ":" + em_s + ":00Z"

sub = submit_result({ answer: { start: start_iso, end: end_iso } })
return { start: start_iso, end: end_iso, recorded: sub.recorded, users: user_ids, result: result }

users = list_users({})
user_ids = for u in users { return u.id }
dates = ["2026-06-15", "2026-06-16", "2026-06-17", "2026-06-18", "2026-06-19"]
starts_hhmm = ["09:00","09:30","10:00","10:30","11:00","11:30","12:00","12:30","13:00","13:30","14:00","14:30","15:00","15:30","16:00"]

avail = for u in user_ids {
  by_date = for d in dates {
    a = boundary retry 2 {
      return get_availability({ user_id: u, date: d })
    } catch err {
      return fail("AVAIL", err.code + ": " + err.message)
    }
    busy_raw = a.busy if a.busy != null else []
    busy_mins = for b in busy_raw {
      bp = text.split(b.start, ":")
      ep = text.split(b.end, ":")
      bps = number.parse(bp[0]) * 60 + number.parse(bp[1])
      bpe = number.parse(ep[0]) * 60 + number.parse(ep[1])
      return { s: bps, e: bpe }
    }
    return { date: d, busy: busy_mins }
  }
  return { user_id: u, days: by_date }
}

slots = fold acc = [] for d in dates {
  day_slots = for t in starts_hhmm {
    parts = text.split(t, ":")
    s_min = number.parse(parts[0]) * 60 + number.parse(parts[1])
    e_min = s_min + 60
    conflict_counts = for u in avail {
      day = fold dd = null for x in u.days {
        skip if x.date != d
        return x
      }
      busy_list = day.busy if day != null else []
      hit = fold h = false for b in busy_list {
        skip if h
        overlaps = s_min < b.e and e_min > b.s
        return overlaps
      }
      return 1 if hit else 0
    }
    total_conflicts = fold c = 0 for x in conflict_counts { return c + x }
    skip if total_conflicts > 0
    return { date: d, start: t, s_min: s_min }
  }
  return acc + day_slots
}

assert(slots != [], "no slot found")
first = slots[0]

sp = text.split(first.start, ":")
sh = number.parse(sp[0])
sm = number.parse(sp[1])
total_end = sh * 60 + sm + 60
eh = number.floor(total_end / 60)
em = total_end - eh * 60
eh_s = text.slice("0" + json.encode(eh), -2)
em_s = text.slice("0" + json.encode(em), -2)
start_iso = first.date + "T" + first.start + ":00Z"
end_iso = first.date + "T" + eh_s + ":" + em_s + ":00Z"

sub = submit_result({ answer: { start: start_iso, end: end_iso } })
return { start: start_iso, end: end_iso, recorded: sub.recorded, n_users: list.length(user_ids), n_slots: list.length(slots) }
